INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Ingin Menyapa Orang Filipina tapi Bingung Mulai dari Mana$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Bahasa Tagalog (resminya disebut Filipino) adalah bahasa nasional Filipina yang dipakai lebih dari 100 juta orang. Banyak orang Indonesia tertarik mempelajarinya karena kedekatan budaya, drama Filipina, atau rencana bekerja di sana. Namun pemula sering bingung: mulai dari apa, bagaimana pengucapannya, dan apa yang sopan diucapkan saat pertama bertemu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Tagalog Itu Lebih Mudah dari yang Dikira$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kabar baik: pengucapan bahasa Tagalog hampir selalu dibaca apa adanya, seperti bahasa Indonesia. Huruf vokal a, e, i, o, u dibaca sama. Kata serapan dari Spanyol dan Inggris sangat banyak (mesa, telepono, kompyuter), jadi kosakata awal terasa familiar. Yang perlu diperhatikan adalah penekanan suku kata dan partikel kesopanan seperti 'po' dan 'opo'.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Aplikasi kamus Tagalog-Indonesia atau Tagalog-Inggris$txt$, $txt$Video percakapan dasar penutur asli (YouTube)$txt$, $txt$Buku catatan kosakata harian$txt$, $txt$Teman latihan atau komunitas belajar bahasa Filipina$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: 10 Sapaan Dasar yang Wajib Dikuasai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Kamusta — Halo, apa kabar (sapaan paling umum)$txt$, $txt$Magandang umaga — Selamat pagi$txt$, $txt$Magandang hapon — Selamat siang/sore$txt$, $txt$Magandang gabi — Selamat malam$txt$, $txt$Salamat — Terima kasih$txt$, $txt$Walang anuman — Sama-sama$txt$, $txt$Paalam — Selamat tinggal$txt$, $txt$Oo / Hindi — Ya / Tidak$txt$, $txt$Pakiusap — Tolong$txt$, $txt$Pasensya na — Maaf$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Kesalahan paling umum: lupa memakai 'po' saat bicara dengan orang yang lebih tua — di Filipina ini dianggap kurang sopan, mirip tidak memakai kata 'pak/bu' di Indonesia. Kesalahan kedua: salah penekanan suku kata yang bisa mengubah arti. Tipsnya: tiru intonasi penutur asli dari video, jangan hanya membaca teks.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Uji kemampuanmu: perkenalkan diri dalam 30 detik memakai bahasa Tagalog (Ako si [nama], taga-Indonesia ako). Jika sudah lancar, lanjutkan ke frasa belanja dan arah jalan, lalu pelajari struktur kalimat dasar. Target 30 hari: bisa melakukan percakapan perkenalan penuh tanpa teks bantuan.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Leher Kaku Setiap Bangun Tidur atau Setelah Kerja$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Leher terasa kaku, sulit menoleh, atau nyeri saat bangun tidur adalah keluhan yang sangat umum, terutama bagi pekerja kantoran dan pengguna HP. Postur menunduk berjam-jam memberi beban berlebih pada otot dan sendi leher. Kabar baiknya: sebagian besar kasus membaik dengan peregangan sederhana yang dilakukan rutin.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Penyebab Umum Sakit Leher$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Penyebab tersering adalah ketegangan otot akibat postur buruk (menunduk ke HP, bantal terlalu tinggi, duduk membungkuk), stres yang membuat otot bahu menegang, dan gerakan tiba-tiba. Sakit leher biasanya membaik dalam beberapa hari hingga dua minggu. Yang perlu diwaspadai adalah nyeri yang menjalar ke lengan disertai kesemutan atau kelemahan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan Sebelum Peregangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Lakukan di tempat duduk yang nyaman dengan punggung tegak$txt$, $txt$Hangatkan dulu dengan kompres hangat 10 menit bila kaku berat$txt$, $txt$Lakukan gerakan perlahan, jangan disentak$txt$, $txt$Bernapas normal selama peregangan, jangan menahan napas$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: 6 Gerakan Peregangan Leher$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Miringkan kepala ke bahu kanan, tahan 20 detik, ulangi ke kiri$txt$, $txt$Tundukkan dagu ke dada perlahan, tahan 20 detik$txt$, $txt$Putar kepala perlahan ke kanan hingga dagu sejajar bahu, tahan 15 detik, ulangi ke kiri$txt$, $txt$Angkat bahu ke telinga, tahan 5 detik, turunkan — ulangi 10 kali$txt$, $txt$Putar bahu ke belakang 10 kali untuk membuka dada$txt$, $txt$Tekan telapak tangan ke dahi, tahan kepala agar tidak bergerak selama 10 detik (penguatan otot)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Hal yang Harus Dihindari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Hindari memutar leher dengan cepat atau memaksakan bunyi 'krek' berlebihan — ini bisa memperparah cedera. Jangan memijat terlalu keras area yang nyeri tajam. Hentikan peregangan jika muncul pusing, nyeri tajam menjalar, atau kesemutan di tangan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kapan Harus ke Dokter$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Segera konsultasi dokter jika: nyeri tidak membaik setelah 2 minggu, nyeri menjalar ke lengan disertai kelemahan atau kesemutan, sakit leher setelah cedera/benturan, disertai demam atau sakit kepala hebat, atau sulit menggerakkan leher sama sekali. Artikel ini adalah informasi umum dan bukan pengganti nasihat medis profesional.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Gunung Berapi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Gunung berapi adalah bukaan di kerak Bumi tempat magma, gas, dan material vulkanik keluar ke permukaan. Sekitar 1.500 gunung berapi aktif tersebar di dunia, sebagian besar berada di Cincin Api Pasifik. Indonesia sendiri memiliki lebih dari 120 gunung berapi aktif — terbanyak di dunia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Krakatau: Letusan Terdahsyat yang Mengguncang Dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Letusan Krakatau pada 27 Agustus 1883 adalah salah satu yang terdahsyat dalam sejarah. Suaranya terdengar hingga Australia dan Mauritius, langit dunia meredup berbulan-bulan, dan tsunami yang ditimbulkannya menewaskan puluhan ribu orang. Dari sisa letusan itu lahir Anak Krakatau yang terus tumbuh hingga kini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Vesuvius: Penghancur Pompeii$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Pada tahun 79 Masehi, Gunung Vesuvius di Italia meletus dan mengubur kota Pompeii dan Herculaneum dalam abu vulkanik. Bencana ini justru mengawetkan kota Romawi kuno secara luar biasa, menjadi jendela ilmu pengetahuan tentang kehidupan 2.000 tahun lalu. Vesuvius masih aktif dan dipantau ketat hingga hari ini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Tipe Gunung Berapi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Gunung berapi dibagi menjadi tiga tipe: perisai (shield) dengan lereng landai seperti Mauna Loa di Hawaii, strato atau kerucut komposit yang curam seperti Merapi dan Fuji, dan kaldera yang terbentuk dari runtuhan raksasa seperti Toba. Tipe letusannya pun berbeda, dari aliran lava tenang hingga ledakan dahsyat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pelajaran Mitigasi Bencana$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Letusan gunung berapi tidak bisa dicegah, tetapi dampaknya bisa dikurangi. Indonesia memiliki sistem peringatan dini berlapis: pemantauan seismik, status level (Normal hingga Awas), peta kawasan rawan bencana, dan jalur evakuasi. Kunci keselamatan adalah mematuhi radius bahaya yang ditetapkan dan tidak kembali ke zona merah sebelum status dinyatakan aman.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Layar: Jendela ke Dunia Digital$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Hampir setiap perangkat modern — HP, laptop, TV — berkomunikasi dengan kita lewat layar. Dalam tiga dekade terakhir, teknologi layar berubah drastis: dari tabung CRT yang besar dan berat, ke LCD yang tipis, hingga OLED yang bisa dilipat. Memahami cara kerjanya membantu kita memilih perangkat dengan lebih cerdas.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$LCD: Sang Pionir Layar Tipis$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$LCD (Liquid Crystal Display) bekerja dengan kristal cair yang mengatur cahaya dari lampu latar (backlight) di belakangnya. Kelebihannya: hemat energi dibanding CRT, harga terjangkau, dan tidak ada risiko burn-in. Kekurangannya: warna hitam tidak pekat karena lampu latar selalu menyala, dan sudut pandang terbatas pada panel murah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$LED dan Perkembangannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Layar 'LED' sebenarnya adalah LCD dengan lampu latar LED, bukan piksel LED sesungguhnya. Varian seperti QLED memakai lapisan quantum dot untuk warna lebih cerah. Teknologi ini mendominasi TV kelas menengah karena terang, awet, dan harganya semakin murah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$OLED: Setiap Piksel Bercahaya Sendiri$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$OLED (Organic Light Emitting Diode) tidak butuh lampu latar — setiap piksel memancarkan cahayanya sendiri dan bisa dimatikan total. Hasilnya: hitam pekat sempurna, kontras tak terbatas, dan layar bisa dibuat fleksibel hingga dilipat. Kekurangannya: harga lebih mahal dan ada risiko burn-in jika gambar statis ditampilkan terlalu lama.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Masa Depan: Layar Lipat dan MicroLED$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Masa depan layar mengarah ke MicroLED — menggabungkan kecerahan LED dengan hitam pekat OLED tanpa risiko burn-in — serta layar yang bisa digulung dan transparan. Dalam beberapa tahun, batas antara HP, tablet, dan TV akan semakin kabur berkat layar fleksibel.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan fungsi sosial lagu dalam bahasa Inggris, (2) mengidentifikasi struktur lirik lagu (verse, chorus, bridge), (3) memahami makna tersirat dalam lirik, dan (4) menyanyikan lagu bahasa Inggris dengan pengucapan yang benar.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian dan Fungsi Sosial Lagu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Song adalah teks fungsional pendek berupa lirik yang dinyanyikan. Fungsi sosialnya adalah menghibur pendengar dan menyampaikan pesan, perasaan, atau cerita penulisnya. Lagu bisa bertema cinta, persahabatan, perjuangan, atau pesan moral.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Struktur Lirik Lagu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Verse — bagian yang menceritakan kisah, biasanya berbeda tiap bait$txt$, $txt$Chorus — bagian yang diulang, berisi pesan utama lagu$txt$, $txt$Bridge — bagian penghubung yang memberi variasi sebelum chorus terakhir$txt$, $txt$Intro dan Outro — pembuka dan penutup lagu$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Unsur Kebahasaan dan Contoh Analisis$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Lirik lagu sering memakai bahasa kiasan (figurative language) seperti simile (perbandingan dengan like/as), metafora, dan repetisi. Perhatikan juga tenses yang dipakai — lagu tentang kenangan biasanya memakai past tense, sedangkan lagu motivasi memakai present atau future tense. Contoh analisis: 'You are my sunshine, my only sunshine' memakai metafora yang membandingkan seseorang dengan sinar matahari; kata 'my only' menekankan betapa istimewanya orang tersebut bagi penyanyi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebutkan tiga bagian struktur lirik lagu beserta fungsinya!$txt$, $txt$Apa fungsi sosial dari sebuah lagu?$txt$, $txt$Jelaskan perbedaan verse dan chorus!$txt$, $txt$Temukan satu contoh simile dalam lagu bahasa Inggris favoritmu!$txt$, $txt$Mengapa lirik lagu sering memakai bahasa kiasan?$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$1. Verse (bercerita), chorus (pesan utama, diulang), bridge (penghubung/variasi). 2. Menghibur dan menyampaikan pesan/perasaan penulis. 3. Verse berbeda tiap bait dan bercerita, chorus diulang dan berisi pesan utama. 4. Contoh: 'like a rolling stone', 'as brave as a lion' — tergantung lagu pilihan. 5. Agar lirik lebih indah, emosional, dan bermakna dalam.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan pengertian dan jenis-jenis pidato, (2) menyusun naskah pidato sederhana dengan struktur yang benar, (3) berpidato di depan kelas dengan lafal, intonasi, dan sikap yang baik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian dan Jenis Pidato$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pidato adalah kegiatan berbicara di depan umum untuk menyampaikan gagasan kepada pendengar. Jenis-jenis pidato antara lain: pidato sambutan (misalnya sambutan ketua kelas), pidato pengarahan, pidato peresmian, dan pidato persuasif yang mengajak pendengar melakukan sesuatu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Struktur Naskah Pidato$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Salam pembuka — misalnya 'Assalamu'alaikum warahmatullahi wabarakatuh, selamat pagi' dan sapaan kepada hadirin$txt$, $txt$Pendahuluan — perkenalan diri dan penyampaian topik pidato$txt$, $txt$Isi — gagasan utama yang disampaikan secara runtut$txt$, $txt$Penutup — simpulan dan ajakan, diakhiri salam penutup$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Teknik Berpidato dan Contoh Naskah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Berpidatolah dengan suara lantang dan jelas, intonasi yang bervariasi agar tidak monoton, kontak mata dengan pendengar, sikap tubuh tegak dan tenang, serta bahasa yang sopan. Latihlah pidatomu di depan cermin atau direkam agar bisa diperbaiki. Contoh naskah bertema kebersihan: 'Assalamu'alaikum warahmatullahi wabarakatuh. Selamat pagi teman-teman yang saya banggakan. Pada kesempatan ini saya akan menyampaikan pidato tentang pentingnya menjaga kebersihan kelas. Kelas yang bersih membuat kita nyaman belajar dan terhindar dari penyakit. Marilah kita biasakan membuang sampah pada tempatnya dan piket sesuai jadwal. Demikian pidato saya, terima kasih. Wassalamu'alaikum warahmatullahi wabarakatuh.'$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebutkan empat jenis pidato beserta contohnya!$txt$, $txt$Tuliskan struktur naskah pidato yang benar!$txt$, $txt$Buatlah naskah pidato singkat bertema 'Rajin Belajar'!$txt$, $txt$Praktikkan pidatomu di depan kelas dengan memperhatikan lafal dan intonasi!$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$1. Sambutan (sambutan ketua kelas), pengarahan (arahan guru), peresmian (pembukaan acara), persuasif (ajakan menjaga kebersihan). 2. Salam pembuka, pendahuluan, isi, penutup. 3. Naskah dinilai dari kelengkapan struktur dan kesesuaian tema. 4. Dinilai dari kelantangan suara, intonasi, kontak mata, dan sikap tubuh.$txt$));
